function makePalindrome(s) {
  let left = 0;
  let right = s.length - 1;
  let changes = 0;

  while (left < right) {
    if (s[left] !== s[right]) {
      changes++;
      if (changes > 2) {
        return false;
      }
    }
    left++;
    right--;
  }
  return true;
}

