function makePalindrome(s) {
  const n = s.length;
  // Try every set of at most two positions we are free to rewrite.
  const fixable = (free) => {
    for (let k = 0; k < n; k++) {
      const m = n - 1 - k;
      if (free.has(k) || free.has(m)) continue;
      if (s[k] !== s[m]) return false;
    }
    return true;
  };
  if (fixable(new Set())) return true;
  for (let i = 0; i < n; i++) {
    if (fixable(new Set([i]))) return true;
    for (let j = i + 1; j < n; j++) if (fixable(new Set([i, j]))) return true;
  }
  return false;
}

