function generate(rand, size) {
  const n = size === 'large' ? 5000 + Math.floor(rand() * 5001) : 1 + Math.floor(rand() * 12);
  const letters = 1 + Math.floor(rand() * (size === 'large' ? 26 : 3));
  const pick = () => String.fromCharCode(97 + Math.floor(rand() * letters));
  // Start from a palindrome, then spoil a few positions so both answers appear.
  const chars = new Array(n);
  for (let i = 0; i < Math.ceil(n / 2); i++) {
    const c = pick();
    chars[i] = c;
    chars[n - 1 - i] = c;
  }
  const spoil = Math.floor(rand() * (size === 'large' ? 5 : 7));
  for (let k = 0; k < spoil; k++) chars[Math.floor(rand() * n)] = String.fromCharCode(97 + Math.floor(rand() * 26));
  return [chars.join('')];
}
